"""Use the original direct-quad corridor for exact or smooth path tables.

This free-span primitive does not claim support for all original-span junction,
Bundle, transition or seam branches. It retains the complete corridor surface
and perimeter guards instead of certifying a strip from the centerline alone.
"""
import bpy
from . import curved_corridor_nodes as corridor

c = corridor.c


def build():
    name = 'Prochitecture Streets / Original exact or smooth free corridor v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    g.socket('Path', 'NodeSocketGeometry')
    for key, default in (('Length', 0.), ('Width', 6.), ('Offset', 0.),
                         ('Rise', .08), ('Datum', 0.), ('Cell Size', 1.),
                         ('Height Exaggeration', 10.)):
        g.socket(key, 'NodeSocketFloat', default=default)
    g.socket('Street ID', 'NodeSocketInt')
    g.socket('Input Valid', 'NodeSocketBool', default=False)
    for key in ('Geometry', 'Inspection Geometry', 'Stations', 'Diagnostics'):
        g.socket(key, 'NodeSocketGeometry', 'OUTPUT')
    for key in ('Valid', 'Inputs Valid', 'Cells Valid', 'Boundary Clear'):
        g.socket(key, 'NodeSocketBool', 'OUTPUT')
    inp = g.node('NodeGroupInput')
    value = lambda key: c.V(g, inp.outputs[key])
    valid = value('Input Valid')*g.math('GREATER_THAN', value('Rise'), -1e-8)
    valid = valid*g.math('LESS_THAN', value('Rise'), 1e3)
    valid = valid*g.math('LESS_THAN', g.math('ABSOLUTE', value('Datum')), 1e6)
    return corridor._density_surface(g, inp, inp.outputs['Path'], 0., value('Length'),
        value('Width'), value('Offset'), 0, value('Rise'), value('Datum'), valid,
        -1, -1, value('Street ID'), value('Cell Size'), free_ends=True, polyline=True)
